    @Autowired TestServices testServices;@Autowired Store db;@Autowired TransactionTemplate tx;@Autowired HireOfferService offers;@Autowired CatalogService catalog;@Autowired AccountService accounts;@Autowired RoleObligations roles;@Autowired MockMvc mvc;
    NguoiDung a,b,c,d,admin;DichVu source;String prefix;
    @BeforeEach void setup(){prefix=UUID.randomUUID().toString();tx.executeWithoutResult(s->{a=TestAccounts.create(db,"Khách hàng A",prefix+"a@test.local","Demo@12345",true,false);b=TestAccounts.create(db,"Chuyên gia B",prefix+"b@test.local","Demo@12345",false,true);c=TestAccounts.create(db,"Khách hàng C",prefix+"c@test.local","Demo@12345",true,false);d=TestAccounts.create(db,"Chuyên gia D",prefix+"d@test.local","Demo@12345",false,true);admin=TestAccounts.create(db,"Quản trị",prefix+"ad@test.local","Demo@12345",false,false);admin.setLaQuanTriVien(true);});source=testServices.create(b.getMaNguoiDung(),null,"Thiết kế sản phẩm","Thiết kế","Nghiên cứu nhu cầu và thiết kế sản phẩm theo từng mốc rõ ràng.",new BigDecimal("2500000"));}
    HireOfferForm form(){HireOfferForm f=new HireOfferForm();f.setTitle("Thiết kế giao diện website");f.setScope("Nghiên cứu nhu cầu, thiết kế giao diện trang chủ và trang sản phẩm.");f.setDeliverable("Bản thiết kế giao diện và tài liệu bàn giao.");f.setPrice("2500000");f.setDays("14");return f;}
    Long create(){return offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),source.getMaDichVu(),UUID.randomUUID().toString(),form());}
    HireOfferService.Details offerView(Long id){return offers.details(a.getMaNguoiDung(),id,1);}
    long count(String type){return tx.execute(s->db.count("select count(x) from "+type+" x"));}
    HireOfferService.Terms revised(Long actor,Long id,int version,String amount){HireOfferForm f=HireOfferService.form(offers.details(actor,id,1).current());f.setPrice(amount);f.setDays("20");f.setReason("Cần thêm thời gian và ngân sách cho phạm vi công việc này.");return offers.previewRevision(actor,id,version,f);}
    @Test void sendingIsSeparateDurableAndBothListsHaveCorrectOwners(){long h=count("HopDong"),g=count("GiaoDich"),y=count("YeuCau"),p=count("DeXuat");Long id=create();var view=offerView(id);assertEquals("CHO_PHAN_HOI",view.row().state());assertEquals(1,view.row().current());assertEquals(b.getMaNguoiDung(),view.row().waiting());assertEquals(1,offers.list(a.getMaNguoiDung(),"da-gui",1).total());assertEquals(1,offers.list(b.getMaNguoiDung(),"nhan",1).total());assertEquals(0,offers.list(c.getMaNguoiDung(),"da-gui",1).total());assertEquals(h,count("HopDong"));assertEquals(g,count("GiaoDich"));assertEquals(y,count("YeuCau"));assertEquals(p,count("DeXuat"));assertEquals(0,view.row().sent().getOffset().getTotalSeconds());}
    @Test void acceptanceIsVersionBoundAndDoesNotCreateMilestonesContractOrMoney()throws Exception{Long id=create();long h=count("HopDong"),g=count("GiaoDich"),m=count("MocNghiemThu");offers.accept(b.getMaNguoiDung(),id,1);offers.accept(b.getMaNguoiDung(),id,1);var view=offerView(id);assertEquals("DA_THONG_NHAT",view.row().state());assertEquals(1,view.agreed());assertEquals(b.getMaNguoiDung(),view.decider());assertNull(view.row().waiting());assertNotNull(view.decided());assertEquals(h,count("HopDong"));assertEquals(g,count("GiaoDich"));assertEquals(m,count("MocNghiemThu"));String body=mvc.perform(get("/de-nghi-thue/"+id).with(user(a.getEmail()))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertTrue(body.contains("Chờ chuyên gia thiết lập mốc"));assertTrue(body.contains("/ke-hoach-moc/thue/"+id));assertFalse(body.contains("/lap-hop-dong"));}
    @Test void rejectionStoresActorReasonAndHistoryAndIsTerminal()throws Exception{Long id=create();offers.reject(b.getMaNguoiDung(),id,1,"Chưa phù hợp với lịch thực hiện hiện tại.");offers.reject(b.getMaNguoiDung(),id,1,"Chưa phù hợp với lịch thực hiện hiện tại.");var view=offerView(id);assertEquals("BI_TU_CHOI",view.row().state());assertEquals(b.getMaNguoiDung(),view.decider());assertNotNull(view.rejection());assertEquals(1,view.history().total());assertThrows(BusinessException.class,()->offers.accept(b.getMaNguoiDung(),id,1));assertThrows(BusinessException.class,()->offers.previewRevision(b.getMaNguoiDung(),id,1,form()));mvc.perform(get("/de-nghi-thue/"+id).with(user(a.getEmail()))).andExpect(content().string(containsString("hire-state--rejected"))).andExpect(content().string(containsString("Chưa phù hợp với lịch thực hiện hiện tại.")));}
    @Test void expertAndCustomerCanAlternateImmutableVersionsThenAgree(){Long id=create();var t2=revised(b.getMaNguoiDung(),id,1,"3000000");offers.revise(b.getMaNguoiDung(),id,1,UUID.randomUUID().toString(),t2);assertEquals(a.getMaNguoiDung(),offerView(id).row().waiting());assertTrue(offerView(id).row().label().contains("Chuyên gia đề nghị điều chỉnh"));assertThrows(AccessDeniedException.class,()->offers.accept(b.getMaNguoiDung(),id,2));var t3=revised(a.getMaNguoiDung(),id,2,"2800000");offers.revise(a.getMaNguoiDung(),id,2,UUID.randomUUID().toString(),t3);assertEquals(b.getMaNguoiDung(),offerView(id).row().waiting());assertTrue(offerView(id).row().label().contains("Chờ chuyên gia phản hồi điều chỉnh"));assertThrows(AccessDeniedException.class,()->offers.accept(a.getMaNguoiDung(),id,3));offers.accept(b.getMaNguoiDung(),id,3);var view=offerView(id);assertEquals(3,view.agreed());assertEquals(3,view.history().total());var original=view.history().items().get(2);assertEquals(0,original.price().compareTo(new BigDecimal("2500000")));assertEquals(14,original.days());assertEquals(a.getMaNguoiDung(),original.author());assertNull(original.reason());}
    @Test void customerCanAcceptExpertRevisionOrRejectWithReason(){Long id=create();offers.revise(b.getMaNguoiDung(),id,1,UUID.randomUUID().toString(),revised(b.getMaNguoiDung(),id,1,"3100000"));offers.accept(a.getMaNguoiDung(),id,2);assertEquals(2,offerView(id).agreed());Long second=create();offers.revise(b.getMaNguoiDung(),second,1,UUID.randomUUID().toString(),revised(b.getMaNguoiDung(),second,1,"3300000"));offers.reject(a.getMaNguoiDung(),second,2,"Ngân sách điều chỉnh vượt phạm vi dự kiến.");assertEquals(a.getMaNguoiDung(),offerView(second).decider());}
    @Test void senderCannotApproveInitialOrOwnRevisedContent(){Long id=create();assertThrows(AccessDeniedException.class,()->offers.accept(a.getMaNguoiDung(),id,1));assertThrows(AccessDeniedException.class,()->offers.reject(a.getMaNguoiDung(),id,1,"Tự từ chối đề nghị đang chờ người khác."));offers.revise(b.getMaNguoiDung(),id,1,UUID.randomUUID().toString(),revised(b.getMaNguoiDung(),id,1,"3200000"));assertThrows(AccessDeniedException.class,()->offers.accept(b.getMaNguoiDung(),id,2));}
    @Test void outsideAndAdminCannotMutateOtherPeoplesOffersAndPrivateDataDoesNotLeak()throws Exception{Long id=create();assertThrows(AccessDeniedException.class,()->offers.details(c.getMaNguoiDung(),id,1));assertThrows(AccessDeniedException.class,()->offers.accept(admin.getMaNguoiDung(),id,1));mvc.perform(get("/de-nghi-thue/"+id).with(user(c.getEmail()))).andExpect(status().isForbidden());mvc.perform(get("/de-nghi-thue/"+id+"/chap-thuan").param("phienBan","1").with(user(d.getEmail()))).andExpect(status().isForbidden());assertEquals(id,offers.details(admin.getMaNguoiDung(),id,1).row().id());assertThrows(AccessDeniedException.class,()->offers.list(c.getMaNguoiDung(),"tat-ca",1));String body=mvc.perform(get("/de-nghi-thue/"+id).with(user(b.getEmail()))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertFalse(body.contains(a.getEmail()));assertFalse(body.contains(a.getMatKhauBam()));}
    @Test void customerRoleSelfHiringSourceOwnershipAndVisibilityAreChecked(){assertThrows(AccessDeniedException.class,()->offers.create(b.getMaNguoiDung(),d.getMaNguoiDung(),null,UUID.randomUUID().toString(),form()));tx.executeWithoutResult(s->db.get(NguoiDung.class,a.getMaNguoiDung()).setLaChuyenGia(true));assertThrows(AccessDeniedException.class,()->offers.create(a.getMaNguoiDung(),a.getMaNguoiDung(),null,UUID.randomUUID().toString(),form()));assertThrows(BusinessException.class,()->offers.create(a.getMaNguoiDung(),d.getMaNguoiDung(),source.getMaDichVu(),UUID.randomUUID().toString(),form()));catalog.visibility(b.getMaNguoiDung(),source.getMaDichVu(),false);assertThrows(BusinessException.class,()->create());Long direct=offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,UUID.randomUUID().toString(),form());assertNull(offerView(direct).row().source());}
    @Test void validationRejectsInvalidMoneyDaysAndMissingText(){for(String amount:List.of("0","-1","1.5","1e3","1000000000001","x")){HireOfferForm f=form();f.setPrice(amount);assertThrows(BusinessException.class,()->offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,UUID.randomUUID().toString(),f));}for(String days:List.of("0","-1","731","1.5","x")){HireOfferForm f=form();f.setDays(days);assertThrows(BusinessException.class,()->offers.validate(f,false));}HireOfferForm empty=form();empty.setDeliverable("");assertThrows(BusinessException.class,()->offers.validate(empty,false));HireOfferForm tooLong=form();tooLong.setScope("x".repeat(10001));assertThrows(BusinessException.class,()->offers.validate(tooLong,false));Long id=create();assertThrows(BusinessException.class,()->offers.reject(b.getMaNguoiDung(),id,1," "));HireOfferForm adjustment=HireOfferService.form(offerView(id).current());assertThrows(BusinessException.class,()->offers.previewRevision(b.getMaNguoiDung(),id,1,adjustment));}
    @Test void repeatedCreateAndRevisionHaveSingleDatabaseEffect(){String key=UUID.randomUUID().toString();Long id=offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,key,form());assertEquals(id,offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,key,form()));HireOfferForm changed=form();changed.setPrice("4000000");assertThrows(BusinessException.class,()->offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,key,changed));String op=UUID.randomUUID().toString();var t=revised(b.getMaNguoiDung(),id,1,"2900000");offers.revise(b.getMaNguoiDung(),id,1,op,t);offers.revise(b.getMaNguoiDung(),id,1,op,t);assertEquals(2,offerView(id).history().total());assertEquals(1,offers.list(a.getMaNguoiDung(),"da-gui",1).total());}
    @Test void staleVersionsRequireReloadAndCannotBeAccepted(){Long id=create();var t=revised(b.getMaNguoiDung(),id,1,"3000000");offers.revise(b.getMaNguoiDung(),id,1,UUID.randomUUID().toString(),t);assertThrows(BusinessException.class,()->offers.accept(a.getMaNguoiDung(),id,1));assertThrows(BusinessException.class,()->offers.reject(a.getMaNguoiDung(),id,1,"Đã xem nhầm phiên bản cũ."));assertEquals("CHO_PHAN_HOI",offerView(id).row().state());assertEquals(2,offerView(id).row().current());}
    @Test void openAndAgreedOffersBlockCorrectRoleButRejectedHistoryDoesNot(){tx.executeWithoutResult(s->{db.get(NguoiDung.class,a.getMaNguoiDung()).setLaChuyenGia(true);db.get(NguoiDung.class,c.getMaNguoiDung()).setLaChuyenGia(true);});Long id=create();assertTrue(Boolean.TRUE.equals(tx.execute(s->roles.outstanding(a.getMaNguoiDung(),true))));assertFalse(Boolean.TRUE.equals(tx.execute(s->roles.outstanding(a.getMaNguoiDung(),false))));assertTrue(Boolean.TRUE.equals(tx.execute(s->roles.outstanding(b.getMaNguoiDung(),false))));assertFalse(Boolean.TRUE.equals(tx.execute(s->roles.outstanding(b.getMaNguoiDung(),true))));AccountForm af=accounts.form(a.getMaNguoiDung());af.setKhach(false);af.setChuyenGia(true);assertThrows(BusinessException.class,()->accounts.profile(a.getMaNguoiDung(),af));offers.accept(b.getMaNguoiDung(),id,1);assertThrows(BusinessException.class,()->accounts.profile(a.getMaNguoiDung(),af));Long second=offers.create(c.getMaNguoiDung(),d.getMaNguoiDung(),null,UUID.randomUUID().toString(),form());offers.reject(d.getMaNguoiDung(),second,1,"Chưa phù hợp phạm vi công việc.");AccountForm cf=accounts.form(c.getMaNguoiDung());cf.setKhach(false);cf.setChuyenGia(true);accounts.profile(c.getMaNguoiDung(),cf);assertEquals("BI_TU_CHOI",offers.details(c.getMaNguoiDung(),second,1).row().state());}
    int race(Callable<?> left,Callable<?> right)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{List<Future<Boolean>> tasks=new ArrayList<>();for(Callable<?> operation:List.of(left,right))tasks.add(pool.submit(()->{gate.await();try{operation.call();return true;}catch(BusinessException|AccessDeniedException expected){return false;}}));gate.countDown();int successes=0;for(var task:tasks)if(task.get(30,TimeUnit.SECONDS))successes++;return successes;}finally{pool.shutdownNow();}}
    @Test void acceptAndRejectRacingHaveOneFinalDecision()throws Exception{Long id=create();assertEquals(1,race(()->{offers.accept(b.getMaNguoiDung(),id,1);return true;},()->{offers.reject(b.getMaNguoiDung(),id,1,"Không thể nhận công việc thời gian này.");return true;}));assertTrue(Set.of("DA_THONG_NHAT","BI_TU_CHOI").contains(offerView(id).row().state()));assertEquals(1L,tx.execute(s->db.count("select count(n) from NhatKyXuLy n where n.loaiDoiTuong='DeNghiThue' and n.maDoiTuong=:id and n.hanhDong in ('THONG_NHAT_DE_NGHI','TU_CHOI_DE_NGHI')","id",id)).longValue());}
    @Test void simultaneousCreateAndRevisionRetriesDoNotDuplicate()throws Exception{String key=UUID.randomUUID().toString();assertEquals(2,race(()->offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,key,form()),()->offers.create(a.getMaNguoiDung(),b.getMaNguoiDung(),null,key,form())));assertEquals(1,offers.list(a.getMaNguoiDung(),"da-gui",1).total());Long id=offers.list(a.getMaNguoiDung(),"da-gui",1).items().get(0).id();var terms=revised(b.getMaNguoiDung(),id,1,"3500000");String op=UUID.randomUUID().toString();assertEquals(2,race(()->offers.revise(b.getMaNguoiDung(),id,1,op,terms),()->offers.revise(b.getMaNguoiDung(),id,1,op,terms)));assertEquals(2,offerView(id).history().total());}
    @Test void expertRoleRemovalAndOfferCreationCannotBothSucceed()throws Exception{AccountForm f=accounts.form(b.getMaNguoiDung());f.setKhach(true);f.setChuyenGia(false);assertEquals(1,race(()->create(),()->{accounts.profile(b.getMaNguoiDung(),f);return true;}));boolean expert=tx.execute(s->db.get(NguoiDung.class,b.getMaNguoiDung()).getLaChuyenGia());assertEquals(expert?1:0,offers.list(a.getMaNguoiDung(),"da-gui",1).total());}
    @Test void customerRoleRemovalAndOfferCreationCannotBothSucceed()throws Exception{AccountForm f=accounts.form(a.getMaNguoiDung());f.setKhach(false);f.setChuyenGia(true);assertEquals(1,race(()->create(),()->{accounts.profile(a.getMaNguoiDung(),f);return true;}));boolean customer=tx.execute(s->db.get(NguoiDung.class,a.getMaNguoiDung()).getLaKhachHang());assertEquals(customer?1:0,offers.list(a.getMaNguoiDung(),"da-gui",1).total());}
    @Test void getPagesNeverDecideAndPostRequiresCsrf()throws Exception{Long id=create();long logs=tx.execute(s->db.count("select count(n) from NhatKyXuLy n where n.loaiDoiTuong='DeNghiThue' and n.maDoiTuong=:id","id",id));for(String path:List.of("/de-nghi-thue/"+id,"/de-nghi-thue/"+id+"/chap-thuan?phienBan=1","/de-nghi-thue/"+id+"/dieu-chinh?phienBan=1","/de-nghi-thue/"+id+"/tu-choi?phienBan=1"))mvc.perform(get(path).with(user(b.getEmail()))).andExpect(status().isOk());assertEquals("CHO_PHAN_HOI",offerView(id).row().state());assertEquals(logs,tx.execute(s->db.count("select count(n) from NhatKyXuLy n where n.loaiDoiTuong='DeNghiThue' and n.maDoiTuong=:id","id",id)).longValue());mvc.perform(post("/de-nghi-thue/"+id+"/xac-nhan").with(user(b.getEmail())).param("token","bad")).andExpect(status().isForbidden());mvc.perform(get("/de-nghi-thue/nhan")).andExpect(redirectedUrlPattern("**/dang-nhap"));}
    @Test void webCreateUsesServerBoundRecipientSourceAndReplaysSafely()throws Exception{MockHttpSession session=new MockHttpSession();var page=mvc.perform(get("/de-nghi-thue/gui/chuyen-gia/"+b.getMaNguoiDung()).param("dichVu",source.getMaDichVu().toString()).session(session).with(user(a.getEmail()))).andExpect(status().isOk()).andReturn();String token=(String)page.getModelAndView().getModel().get("token");assertEquals(source.getMoTa(),((HireOfferForm)page.getModelAndView().getModel().get("form")).getScope());var f=form();var review=mvc.perform(post("/de-nghi-thue/gui").session(session).with(user(a.getEmail())).with(csrf()).param("token",token).param("title",f.getTitle()).param("scope",f.getScope()).param("deliverable",f.getDeliverable()).param("price",f.getPrice()).param("days",f.getDays())).andExpect(view().name("hire-create-review")).andReturn();assertEquals(0,offers.list(a.getMaNguoiDung(),"da-gui",1).total());String confirm=(String)review.getModelAndView().getModel().get("token");for(int i=0;i<2;i++)mvc.perform(post("/de-nghi-thue/gui/xac-nhan").session(session).with(user(a.getEmail())).with(csrf()).param("token",confirm)).andExpect(status().isFound());assertEquals(1,offers.list(a.getMaNguoiDung(),"da-gui",1).total());var row=offers.list(a.getMaNguoiDung(),"da-gui",1).items().get(0);assertEquals(b.getMaNguoiDung(),row.expert());assertEquals(source.getMaDichVu(),row.source());mvc.perform(post("/de-nghi-thue/gui").session(session).with(user(c.getEmail())).with(csrf()).param("token",token)).andExpect(status().isForbidden());}
    @Test void serverConfirmationRejectsChangedUrlAndStaleTicket()throws Exception{Long id=create(),other=create();MockHttpSession session=new MockHttpSession();var page=mvc.perform(get("/de-nghi-thue/"+id+"/chap-thuan").param("phienBan","1").session(session).with(user(b.getEmail()))).andExpect(status().isOk()).andReturn();String token=(String)page.getModelAndView().getModel().get("token");mvc.perform(post("/de-nghi-thue/"+other+"/xac-nhan").session(session).with(user(b.getEmail())).with(csrf()).param("token",token)).andExpect(status().isForbidden());offers.revise(b.getMaNguoiDung(),id,1,UUID.randomUUID().toString(),revised(b.getMaNguoiDung(),id,1,"3300000"));mvc.perform(post("/de-nghi-thue/"+id+"/xac-nhan").session(session).with(user(b.getEmail())).with(csrf()).param("token",token).param("phienBan","2")).andExpect(redirectedUrl("/de-nghi-thue/"+id)).andExpect(flash().attributeExists("error"));assertEquals("CHO_PHAN_HOI",offerView(id).row().state());}
    @Test void confirmedRevisionUsesExactlyReviewedTermsAndShowsChanges()throws Exception{Long id=create();MockHttpSession session=new MockHttpSession();var result=mvc.perform(post("/de-nghi-thue/"+id+"/dieu-chinh/ra-soat").session(session).with(user(b.getEmail())).with(csrf()).param("phienBan","1").param("scope",form().getScope()).param("deliverable",form().getDeliverable()).param("price","3000000").param("days","20").param("reason","Cần thêm thời gian cho nội dung yêu cầu.")).andExpect(status().isOk()).andExpect(view().name("hire-confirm")).andExpect(content().string(containsString("Giá thay đổi"))).andReturn();assertEquals(1,offerView(id).row().current());String token=(String)result.getModelAndView().getModel().get("token");for(int i=0;i<2;i++)mvc.perform(post("/de-nghi-thue/"+id+"/xac-nhan").session(session).with(user(b.getEmail())).with(csrf()).param("token",token).param("price","1")).andExpect(redirectedUrl("/de-nghi-thue/"+id));assertEquals(2,offerView(id).row().current());assertEquals(0,offerView(id).current().price().compareTo(new BigDecimal("3000000")));}
    @Test void workspaceLinksAreSeparateForBothRolesAndListsArePaged()throws Exception{tx.executeWithoutResult(s->{db.get(NguoiDung.class,a.getMaNguoiDung()).setLaChuyenGia(true);db.get(NguoiDung.class,b.getMaNguoiDung()).setLaKhachHang(true);});for(int i=0;i<13;i++)create();offers.create(b.getMaNguoiDung(),a.getMaNguoiDung(),null,UUID.randomUUID().toString(),form());assertEquals(12,offers.list(a.getMaNguoiDung(),"da-gui",1).items().size());assertEquals(1,offers.list(a.getMaNguoiDung(),"da-gui",2).items().size());String html=mvc.perform(get("/bang-dieu-khien").with(user(a.getEmail()))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertTrue(html.contains("Đề nghị thuê đã gửi (13)"));assertTrue(html.contains("Đề nghị thuê nhận được (1)"));assertTrue(html.contains("Đề xuất đã gửi"));assertTrue(html.contains("Đề xuất nhận được"));}
    @Test void captureAllNegotiationStatesForVisualQa()throws Exception{Path folder=Path.of(".run","hire-qa","rendered");Files.createDirectories(folder);Long id=create();capture(folder,"waiting",get("/de-nghi-thue/"+id).with(user(b.getEmail())));capture(folder,"sent",get("/de-nghi-thue/da-gui").with(user(a.getEmail())));capture(folder,"received",get("/de-nghi-thue/nhan").with(user(b.getEmail())));capture(folder,"form",get("/de-nghi-thue/gui/chuyen-gia/"+b.getMaNguoiDung()).param("dichVu",source.getMaDichVu().toString()).with(user(a.getEmail())));capture(folder,"edit",get("/de-nghi-thue/"+id+"/dieu-chinh").param("phienBan","1").with(user(b.getEmail())));capture(folder,"confirm",get("/de-nghi-thue/"+id+"/chap-thuan").param("phienBan","1").with(user(b.getEmail())));capture(folder,"reject-form",get("/de-nghi-thue/"+id+"/tu-choi").param("phienBan","1").with(user(b.getEmail())));capture(folder,"compare",post("/de-nghi-thue/"+id+"/dieu-chinh/ra-soat").param("phienBan","1").param("scope",form().getScope()).param("deliverable",form().getDeliverable()).param("price","3000000").param("days","20").param("reason","Cần thêm thời gian và ngân sách cho phạm vi này.").with(user(b.getEmail())).with(csrf()));capture(folder,"reject-confirm",post("/de-nghi-thue/"+id+"/tu-choi/ra-soat").param("phienBan","1").param("reason","Thời gian hiện tại chưa phù hợp với lịch làm việc.").with(user(b.getEmail())).with(csrf()));capture(folder,"dashboard-customer",get("/bang-dieu-khien").with(user(a.getEmail())));capture(folder,"dashboard-expert",get("/bang-dieu-khien").with(user(b.getEmail())));offers.revise(b.getMaNguoiDung(),id,1,UUID.randomUUID().toString(),revised(b.getMaNguoiDung(),id,1,"3000000"));capture(folder,"revised",get("/de-nghi-thue/"+id).with(user(a.getEmail())));offers.accept(a.getMaNguoiDung(),id,2);capture(folder,"agreed",get("/de-nghi-thue/"+id).with(user(a.getEmail())));Long rejected=create();offers.reject(b.getMaNguoiDung(),rejected,1,"Thời gian dự kiến chưa phù hợp với lịch làm việc hiện tại.");capture(folder,"rejected",get("/de-nghi-thue/"+rejected).with(user(a.getEmail())));}
    @Test void rejectionRequiresReviewAndFinalPostUsesReviewedReason()throws Exception{Long id=create();MockHttpSession session=new MockHttpSession();var review=mvc.perform(post("/de-nghi-thue/"+id+"/tu-choi/ra-soat").session(session).with(user(b.getEmail())).with(csrf()).param("phienBan","1").param("reason","Không phù hợp với lịch làm việc hiện tại.")).andExpect(status().isOk()).andExpect(view().name("hire-confirm")).andReturn();assertEquals("CHO_PHAN_HOI",offerView(id).row().state());String token=(String)review.getModelAndView().getModel().get("token");for(int i=0;i<2;i++)mvc.perform(post("/de-nghi-thue/"+id+"/xac-nhan").session(session).with(user(b.getEmail())).with(csrf()).param("token",token).param("reason","Nội dung bị sửa ở client")).andExpect(redirectedUrl("/de-nghi-thue/"+id));assertEquals("Không phù hợp với lịch làm việc hiện tại.",offerView(id).rejection());}
