    @Test void versionHistoryIsPagedAndNeverReplaced(){Long id=create();for(int n=1;n<=11;n++){Long actor=n%2==1?b.getMaNguoiDung():a.getMaNguoiDung();offers.revise(actor,id,n,UUID.randomUUID().toString(),revised(actor,id,n,Integer.toString(3000000+n)));}var newest=offerView(id);var older=offers.details(a.getMaNguoiDung(),id,2);assertEquals(12,newest.history().total());assertEquals(10,newest.history().items().size());assertEquals(2,older.history().items().size());assertEquals(1,older.history().items().get(1).number());assertEquals(0,older.history().items().get(1).price().compareTo(new BigDecimal("2500000")));assertNotNull(newest.history().next());}
    void capture(Path folder,String name,org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request)throws Exception{Files.write(folder.resolve(name+".html"),mvc.perform(request).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray());}
